local a = game.ReplicatedStorage.Shared.Assets local s = a.Source s = s:gsub("%-%- PASS IDS START.-%-%- PASS IDS END\n", "") local block = "-- PASS IDS START\nAssets.GamePasses = Assets.GamePasses or {}\nAssets.GamePasses.DoubleCoins = 2025200302\nAssets.GamePasses.VIP = 2027162312\nAssets.GamePasses.RocketLauncher = 2026628307\nAssets.GamePasses.DoubleJump = 2026136310\nAssets.GamePasses.TripleJump = 2025812309\nAssets.GamePasses.SpeedCoil = 2025584314\nAssets.GamePasses.GravityCoil = 2026400306\n-- PASS IDS END\n" local n s, n = s:gsub("\nreturn Assets", function() return "\n" .. block .. "return Assets" end, 1) if n == 1 then a.Source = s print("All 7 game pass IDs saved!") else warn("Could not find Assets - tell Claude") end
